namespace sv_80b10bea682d4683b13ebbaa45ac871b.Services;

/// <summary>
/// Scoped service (per-circuit) that holds the currently selected warehouse
/// and the latest low-stock alert count. Provides change-notification events
/// so unrelated components can stay synchronized.
/// </summary>
public sealed class WarehouseStateService : IDisposable
{
    private string _selectedWarehouseId = "WH-001";
    private int _lowStockCount;

    public string SelectedWarehouseId
    {
        get => _selectedWarehouseId;
        set
        {
            if (_selectedWarehouseId == value) return;
            _selectedWarehouseId = value;
            NotifyWarehouseChanged();
        }
    }

    public int LowStockCount
    {
        get => _lowStockCount;
        set
        {
            if (_lowStockCount == value) return;
            _lowStockCount = value;
            NotifyAlertCountChanged();
        }
    }

    /// <summary>Raised when the selected warehouse changes.</summary>
    public event Func<Task>? OnWarehouseChanged;

    /// <summary>Raised when the low-stock alert count changes.</summary>
    public event Func<Task>? OnAlertCountChanged;

    private void NotifyWarehouseChanged()
        => OnWarehouseChanged?.Invoke();

    private void NotifyAlertCountChanged()
        => OnAlertCountChanged?.Invoke();

    public void Dispose()
    {
        OnWarehouseChanged = null;
        OnAlertCountChanged = null;
    }
}

namespace sv_80b10bea682d4683b13ebbaa45ac871b.Services;

/// <summary>
/// Simulates checking inventory levels for a given warehouse.
/// Returns a random low-stock count between 0 and 15.
/// </summary>
public sealed class InventoryAlertService
{
    private readonly Random _random = new();

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async database query
        int count = _random.Next(0, 16);
        return Task.FromResult(count);
    }
}

@rendermode InteractiveServer
@inject Services.WarehouseStateService WarehouseState
@implements IDisposable

<select class="form-select form-select-sm w-auto" value="@WarehouseState.SelectedWarehouseId"
        @onchange="OnWarehouseSelected">
    @foreach (var wh in _warehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    private readonly List<(string Id, string Name)> _warehouses =
    [
        ("WH-001", "Warehouse A - Main"),
        ("WH-002", "Warehouse B - East"),
        ("WH-003", "Warehouse C - West"),
        ("WH-004", "Warehouse D - Overflow")
    ];

    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleStateChanged;
    }

    private async Task HandleStateChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        WarehouseState.SelectedWarehouseId = e.Value?.ToString() ?? _warehouses[0].Id;
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleStateChanged;
    }
}

@rendermode InteractiveServer
@inject Services.WarehouseStateService WarehouseState
@implements IDisposable

<span class="badge @BadgeClass rounded-pill">@WarehouseState.LowStockCount</span>

@code {
    private string BadgeClass => WarehouseState.LowStockCount switch
    {
        0 => "bg-success",
        <= 5 => "bg-warning text-dark",
        _ => "bg-danger"
    };

    protected override void OnInitialized()
    {
        WarehouseState.OnAlertCountChanged += HandleAlertChanged;
        WarehouseState.OnWarehouseChanged += HandleAlertChanged;
    }

    private async Task HandleAlertChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnAlertCountChanged -= HandleAlertChanged;
        WarehouseState.OnWarehouseChanged -= HandleAlertChanged;
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@inject Services.WarehouseStateService WarehouseState
@inject Services.InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-3">
    <div class="card-body">
        <h5 class="card-title">
            Low-Stock Alerts
            <span class="badge @BadgeClass rounded-pill ms-2">@WarehouseState.LowStockCount</span>
        </h5>
        <p class="card-text text-muted">
            Monitoring <strong>@WarehouseState.SelectedWarehouseId</strong> &mdash;
            polling every 10 seconds.
        </p>
        @if (_lastChecked.HasValue)
        {
            <p class="card-text"><small class="text-muted">Last checked: @_lastChecked.Value.ToString("HH:mm:ss")</small></p>
        }
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private DateTime? _lastChecked;

    private string BadgeClass => WarehouseState.LowStockCount switch
    {
        0 => "bg-success",
        <= 5 => "bg-warning text-dark",
        _ => "bg-danger"
    };

    protected override async Task OnInitializedAsync()
    {
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
        WarehouseState.OnAlertCountChanged += HandleAlertChanged;

        // Initial fetch then start polling
        await PollAlertCountAsync();
        StartPolling();
    }

    private void StartPolling()
    {
        _cts?.Cancel();
        _cts = new CancellationTokenSource();
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                await PollAlertCountAsync();
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task PollAlertCountAsync()
    {
        var count = await AlertService.GetLowStockCountAsync(WarehouseState.SelectedWarehouseId);
        _lastChecked = DateTime.Now;
        // Setting this property notifies ALL subscribers (including sidebar badge)
        WarehouseState.LowStockCount = count;
        await InvokeAsync(StateHasChanged);
    }

    private async Task HandleWarehouseChanged()
    {
        // Warehouse changed — immediately re-poll for the new warehouse
        await PollAlertCountAsync();
        StartPolling();
    }

    private async Task HandleAlertChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
        WarehouseState.OnAlertCountChanged -= HandleAlertChanged;
    }
}

