namespace sv_80b10bea682d4683b13ebbaa45ac871b.Services;

/// <summary>
/// Scoped service (per-circuit) that holds the currently selected warehouse
/// and the latest low-stock alert count. Provides change-notification events
/// so unrelated components can stay synchronized.
/// </summary>
public sealed class WarehouseStateService : IDisposable
{
    private string _selectedWarehouseId = "WH-001";
    private int _lowStockCount;

    public string SelectedWarehouseId
    {
        get => _selectedWarehouseId;
        set
        {
            if (_selectedWarehouseId == value) return;
            _selectedWarehouseId = value;
            NotifyWarehouseChanged();
        }
    }

    public int LowStockCount
    {
        get => _lowStockCount;
        set
        {
            if (_lowStockCount == value) return;
            _lowStockCount = value;
            NotifyAlertCountChanged();
        }
    }

    /// <summary>Raised when the selected warehouse changes.</summary>
    public event Func<Task>? OnWarehouseChanged;

    /// <summary>Raised when the low-stock alert count changes.</summary>
    public event Func<Task>? OnAlertCountChanged;

    private void NotifyWarehouseChanged()
        => OnWarehouseChanged?.Invoke();

    private void NotifyAlertCountChanged()
        => OnAlertCountChanged?.Invoke();

    public void Dispose()
    {
        OnWarehouseChanged = null;
        OnAlertCountChanged = null;
    }
}

